mapper.select:
SELECT i.ID AS id, i.SUBJECT AS subject, u.NAME AS memName, sc1.NAME AS statusCd, sc2.NAME AS priorityCd, TO_CHAR(i.DUE_DATE, 'YYYY-MM-DD') AS dueDate, i.DONE_RATIO AS doneRatio FROM ISSUE i LEFT JOIN USERS u ON u.ID = i.MEM_ID LEFT JOIN SUB_CODE sc1 ON sc1.S_CODE = i.STATUS_CD AND sc1.M_CODE = '00ISSUESTAT' LEFT JOIN SUB_CODE sc2 ON sc2.S_CODE = i.PRIORITY_CD AND sc2.M_CODE = '00ISSUEPRI' WHERE i.PRJ_ID IN
#{prjId}
AND i.DUE_DATE BETWEEN TRUNC(SYSDATE) - MOD(TO_NUMBER(TO_CHAR(SYSDATE,'D'))-2, 7) AND TRUNC(SYSDATE) - MOD(TO_NUMBER(TO_CHAR(SYSDATE,'D'))-2, 7) + 6 AND i.STATUS_CD != '04ISSUESTAT' ORDER BY i.DUE_DATE ASC
